function mcpServerUrlFromApiHost(apiHost, path, localPort) {
	const candidate = apiHost.includes("://") ? apiHost : `https://${apiHost}`;
	const apiUrl = URL.canParse(candidate) ? new URL(candidate) : void 0;
	const [apiLabel, ...domain] = apiUrl?.hostname.split(".") ?? [];
	if (apiUrl && [
		"localhost",
		"127.0.0.1",
		"[::1]"
	].includes(apiUrl.hostname) && localPort) return new URL(path, `http://${apiUrl.hostname}:${localPort}`);
	if (apiLabel !== "api" || domain.length === 0) throw new Error(`Cannot derive the aVenture MCP host from API host ${apiHost}`);
	return new URL(path, `https://${["mcp", ...domain].join(".")}`);
}
